import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {ToolRegistry} from './tools/registry.js';

const promptBuilder = new PromptBuilder({identity: 'Usage test.'});
const createSession = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
});

const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};

describe('Usage Aggregation', () => {
  it('aggregates usage across multiple rounds', async () => {
    let round = 0;
    const usage1: UsageMetadata = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const usage2: UsageMetadata = {inputTokens: 20, outputTokens: 10, totalTokens: 30};

    let receivedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register({name: 't1', description: 'tool 1', inputSchema: {type: 'object'}}, async () => 'result');

    const provider: AIProvider = {
      async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round++;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'c1', name: 't1', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use', usage: usage1};
          return;
        }
        yield {type: 'text', text: 'done'};
        yield {type: 'stop', stopReason: 'end_turn', usage: usage2};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('call tool'));

    expect(receivedUsage).toEqual({
      inputTokens: usage1.inputTokens + usage2.inputTokens,
      outputTokens: usage1.outputTokens + usage2.outputTokens,
      totalTokens: usage1.totalTokens + usage2.totalTokens,
    });
  });
});

